negativeExample:
package test;

import org.eclipse.swt.widgets.Composite;
import org.eclipse.swt.widgets.Control;

public class MyCompositeRuler {
    public void updateOther(Control parent) {
        if (parent instanceof Composite && !parent.isDisposed())
            ((Composite) parent).layout(false); // Different argument
    }

    public void updateAnother(Control parent) {
        if (parent instanceof Composite && !parent.isDisposed())
            ((Composite) parent).layout(); // Different method signature
    }

    public void updateWithAll(Control parent) {
        if (parent instanceof Composite && !parent.isDisposed())
            ((Composite) parent).layout(true, false); // Already two args, different second arg
    }
}
